'use strict';
// Original portfolio implementation. All people, places, and schedules are fictional.
const icons = {
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2"/>',
 print:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6zM18 12h.01"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 pill:'<path d="m10 4-6 6a6 6 0 0 0 8 8l6-6a6 6 0 0 0-8-8ZM7 7l10 10"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 leaf:'<path d="M20 3C9 2 2 9 5 16s15 3 15-13ZM5 21 16 10"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
 chevron:'<path d="m9 6 6 6-6 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.calendar}</svg>`;
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const fromKey = key => {const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d,12)};
const addDays = (date, count) => {const d=new Date(date);d.setDate(d.getDate()+count);return d};
const monday = date => addDays(date,-((date.getDay()+6)%7));
const fmt = (date, options) => date.toLocaleDateString('en-US',options);
const formatTime = time => {const [h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`};
const minutes = time => {const [h,m]=time.split(':').map(Number);return h*60+m};
const today = new Date();today.setHours(12,0,0,0);
const KEY='kindred-care-demo-v1';
function seed(){
 const start=monday(today), events=[];
 const make=(offset,time,title,category,duration,location,partner,notes='')=>events.push({id:`seed-${events.length}`,date:dateKey(addDays(start,offset)),time,title,category,duration,location,partner,notes});
 for(let day=0;day<7;day++){
  make(day,'08:00','Morning medication','medication',30,'At home','Alex Morgan','Fictional reminder for the demo; no medication or dosage instructions.');
  make(day,'17:00','Evening check-in','activity',30,'At home','Jamie Morgan','A little time to catch up and plan tomorrow.');
 }
 make(0,'10:00','Physical therapy','appointment',60,'Willow Wellness','Robin Chen','Bring comfortable shoes and the appointment folder.');
 make(1,'11:00','Garden & fresh air','activity',60,'Community garden','Jamie Morgan','A gentle outing, weather permitting.');
 make(2,'09:30','Care team catch-up','appointment',60,'Video call','Alex Morgan','Review the weekly schedule together.');
 make(3,'10:00','Physical therapy','appointment',60,'Willow Wellness','Robin Chen','Bring comfortable shoes and the appointment folder.');
 make(3,'10:30','Care partner handoff','activity',30,'Willow Wellness','Alex Morgan','Meet Robin after the session.');
 make(4,'13:00','Library afternoon','activity',90,'Oak Street Library','Jamie Morgan','Pick out something good to read.');
 make(5,'12:00','Lunch with Jamie','activity',90,'At home','Jamie Morgan','A relaxed weekend lunch.');
 make(6,'10:00','Weekly care planning','appointment',60,'At home','Alex Morgan','Look ahead to next week.');
 // Guarantee a useful overview on any day of the week.
 if(!events.some(e=>e.date===dateKey(today)&&e.category==='appointment'))make((today.getDay()+6)%7,'14:00','Care partner visit','appointment',60,'At home','Robin Chen','Review the week and spend some time together.');
 return {version:1,week:dateKey(start),events,completed:[]};
}
let storageAvailable=true;
function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return seed();const data=JSON.parse(raw);if(data.version!==1||!Array.isArray(data.events)||!Array.isArray(data.completed))throw Error('invalid data');for(const e of data.events){if(!e.id||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||!/^\d{2}:\d{2}$/.test(e.time)||!['appointment','activity','medication'].includes(e.category)||![30,60,90].includes(e.duration)||typeof e.title!=='string')throw Error('invalid event')}return data}catch{return seed()}}
let state=load(), week=monday(today), selected=dateKey(today), currentView=['overview','calendar','plan','about'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
let toastTimer;
function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false;notify('Browser storage unavailable. Changes last for this visit only.')}}
function weekly(){const end=dateKey(addDays(week,6)),start=dateKey(week);return state.events.filter(e=>e.date>=start&&e.date<=end).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time))}
const dayEvents = key => state.events.filter(e=>e.date===key).sort((a,b)=>a.time.localeCompare(b.time));
const rangeLabel=()=>`${fmt(week,{month:'short',day:'numeric'})} – ${fmt(addDays(week,6),{month:'short',day:'numeric',year:'numeric'})}`;
const categoryIcon = category => ({appointment:'calendar',activity:'leaf',medication:'pill'}[category]);
const displayNames={overview:'Overview',calendar:'Calendar',plan:'Care plan',about:'About this demo'};
function go(view){if(currentView===view){render();return}currentView=view;history.replaceState(null,'',`#${view}`);render();document.getElementById('main').focus()}
function buttons(){return `<div class="heading-actions"><button class="button secondary" data-action="print">${icon('print')} Print care plan</button><button class="button primary" data-action="add">${icon('plus')} Add appointment</button></div>`}
function heading(tag,title,subtitle,actions=true){return `<div class="page-heading"><div><div class="greeting-tag">${tag}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?buttons():''}</div>`}
function profile(){return `<div class="profile-card"><div class="profile-avatar" aria-hidden="true">EM</div><div class="profile-info"><span class="eyebrow">CARING TOGETHER FOR</span><h2>Evelyn Morgan</h2><p>Enjoys gardening, mystery novels & a good cup of tea.</p></div><div class="profile-meta"><p>YOUR ROLE</p><strong>Care coordinator</strong></div></div>`}
function team(){return `<div class="card"><div class="card-label"><h2>Your care circle</h2><small>3 partners</small></div>${[['AM','Alex Morgan','Care coordinator · You'],['JM','Jamie Morgan','Family care partner'],['RC','Robin Chen','Visiting care partner']].map(([initials,name,role])=>`<div class="care-member"><div class="avatar">${initials}</div><div><strong>${name}</strong><small>${role}</small></div></div>`).join('')}<div class="card-footer">A shared plan. A little less to carry.<br>All people and care details are fictional.</div></div>`}
function scheduleRows(events){if(!events.length)return '<div class="empty">A little breathing room.<br>No events planned for this day.</div>';return `<div class="schedule-list">${events.map(e=>{const done=state.completed.includes(e.id);return `<div class="schedule-row"><div class="time">${formatTime(e.time).split(' ')[0]}<small>${formatTime(e.time).split(' ')[1]}</small></div><div class="event-icon ${e.category}">${icon(categoryIcon(e.category))}</div><button class="view-link event-copy ${done?'done-copy':''}" data-edit="${escapeHtml(e.id)}"><strong>${escapeHtml(e.title)}</strong><small>${escapeHtml(e.location||'Location not set')} · ${escapeHtml(e.partner)}</small></button><button class="check ${done?'done':''}" aria-label="${done?'Mark incomplete':'Mark complete'}: ${escapeHtml(e.title)}" aria-pressed="${done}" data-check="${escapeHtml(e.id)}">${done?icon('check'):''}</button></div>`}).join('')}</div>`}
function overview(){const events=dayEvents(selected),todays=dayEvents(dateKey(today)),done=todays.filter(e=>state.completed.includes(e.id)).length;const greeting='A little more peace of mind.';return `<section>${heading('EVERYDAY CARE, TOGETHER',greeting,'A shared view of the little things that make a big difference.') }<div class="overview-grid"><div>${profile()}<div class="stats">${[[icon('calendar'),todays.filter(e=>e.category==='appointment').length,'Appointments','Planned for today'],[icon('pill'),todays.filter(e=>e.category==='medication').length,'Reminders','Fictional daily routine'],[icon('check'),`${done}<span style="font-size:16px;color:var(--muted)"> / ${todays.length}</span>`,'Completed','One thing at a time']].map(([svg,value,label,caption])=>`<div class="stat"><div class="stat-top"><span>${label}</span><div class="stat-icon">${svg}</div></div><div class="stat-value">${value}</div><div class="stat-caption">${caption}</div></div>`).join('')}</div><div class="section-heading"><h2>${selected===dateKey(today)?'Today’s rhythm':fmt(fromKey(selected),{weekday:'long'})+'’s rhythm'}</h2><span>${fmt(fromKey(selected),{month:'long',day:'numeric'})}</span></div><div class="week-preview">${Array.from({length:7},(_,i)=>{const date=addDays(monday(today),i),key=dateKey(date);return `<button class="day-chip ${selected===key?'selected':''} ${dayEvents(key).length?'has-event':''}" data-day="${key}" aria-pressed="${selected===key}" aria-label="${fmt(date,{weekday:'long',month:'long',day:'numeric'})}">${fmt(date,{weekday:'short'})}<strong>${date.getDate()}</strong></button>`}).join('')}</div><div class="card">${scheduleRows(events)}</div><div class="section-heading week-mini"><span>Small steps count. Check off a task when it’s done.</span><button class="text-button" data-view="calendar">See full calendar ${icon('arrow')}</button></div></div><aside class="right-column">${team()}<div class="gentle-card"><div class="flower" aria-hidden="true">✳</div><span class="eyebrow">A GENTLE REMINDER</span><h3 style="margin-top:10px">Care includes you, too.</h3><p>You don’t have to do everything today. Make a little room for a walk, a pause, or a cup of something warm.</p></div><div class="card"><div class="card-label"><h2>A plan to take along</h2>${icon('print')}</div><p style="font-size:12px;color:var(--muted);line-height:1.8;margin-bottom:15px">Keep the week close at hand with a simple, printable care plan.</p><button class="text-button" data-view="plan">Preview care plan ${icon('arrow')}</button></div></aside></div></section>`}
// Interval partitioning: events in the same overlapping group share available width.
function positionEvents(events){const items=events.map(e=>({...e,start:minutes(e.time),end:minutes(e.time)+e.duration})).sort((a,b)=>a.start-b.start||b.duration-a.duration);let group=[],groupEnd=-1;const output=[];function flush(){if(!group.length)return;const lanes=[];for(const e of group){let lane=lanes.findIndex(end=>end<=e.start);if(lane<0)lane=lanes.length;lanes[lane]=e.end;e.lane=lane}for(const e of group)output.push({...e,lanes:lanes.length});group=[]}for(const e of items){if(e.start>=groupEnd){flush();groupEnd=e.end}group.push(e);groupEnd=Math.max(groupEnd,e.end)}flush();return output}
function calendarView(){return `<section>${heading('ONE WEEK, ONE SHARED PLAN','Room for what matters.','Appointments, daily routines, and time together—in one place.')}<div class="calendar-toolbar"><div class="week-control"><div class="week-arrows"><button class="icon-button" data-action="prev" aria-label="Previous week">‹</button><button class="icon-button" data-action="next" aria-label="Next week">›</button></div><h2>${rangeLabel()}</h2><button class="button secondary" data-action="today">This week</button></div><div class="legend"><span><i style="background:#d59d7e"></i>Appointment</span><span><i style="background:#9bb48c"></i>Activity</span><span><i style="background:#ac9cc9"></i>Reminder</span></div></div><div class="calendar-wrap" tabindex="0" role="region" aria-label="Weekly calendar. Scroll horizontally on small screens."><div class="calendar"><div class="calendar-head"><div></div>${Array.from({length:7},(_,i)=>{const d=addDays(week,i);return `<div class="calendar-day ${dateKey(d)===dateKey(today)?'today':''}">${fmt(d,{weekday:'short'}).toUpperCase()}<strong>${d.getDate()}</strong></div>`}).join('')}</div><div class="calendar-body"><div class="time-axis">${Array.from({length:11},(_,i)=>`<span class="hour" style="--hour:${i}">${(i+8)%12||12} ${i+8<12?'AM':'PM'}</span>`).join('')}</div>${Array.from({length:7},(_,i)=>{const key=dateKey(addDays(week,i));return `<div class="calendar-column ${key===dateKey(today)?'today':''}">${positionEvents(dayEvents(key)).map(e=>`<button class="calendar-event ${e.category} ${e.duration===30?'compact':''}" data-edit="${escapeHtml(e.id)}" style="top:${e.start-480}px;height:${e.duration-1}px;left:calc(${e.lane/e.lanes*100}% + 3px);width:calc(${100/e.lanes}% - 6px);z-index:${e.lane+1}" title="${escapeHtml(e.title)} · ${formatTime(e.time)}" aria-label="${escapeHtml(e.title)}, ${fmt(fromKey(e.date),{weekday:'long'})}, ${formatTime(e.time)}, ${e.duration} minutes">${formatTime(e.time)}<strong>${escapeHtml(e.title)}</strong>${e.duration>=60?`<small>${escapeHtml(e.location)}</small>`:''}</button>`).join('')}</div>`}).join('')}</div></div></div><p class="calendar-note">${icon('info')} Select an event to view or edit it. Calendar hours: 8 AM–7 PM.</p></section>`}
function carePlan(){const events=weekly();let last='';return `<section class="plan-view">${heading('A LITTLE CLARITY, ON PAPER','The week, within reach.','A simple care plan for Evelyn. Preview it here, or take a copy along.',false)}<div class="no-print calendar-toolbar"><div class="week-control"><div class="week-arrows"><button class="icon-button" data-action="prev" aria-label="Previous week">‹</button><button class="icon-button" data-action="next" aria-label="Next week">›</button></div><h2>${rangeLabel()}</h2><button class="button secondary" data-action="today">This week</button></div><button class="button primary" data-action="print">${icon('print')} Print / save PDF</button></div><div class="print-header"><div><h1>Kindred · Weekly care plan</h1><p>Evelyn Morgan · ${rangeLabel()}</p></div><p>FICTIONAL PORTFOLIO DEMO<br>No real care or medication instructions.</p></div><div class="plan-intro"><div class="card"><h2 style="font-size:16px">Evelyn Morgan</h2><div class="plan-list"><div><span>Care coordinator</span><strong>Alex Morgan</strong></div><div><span>Family care partner</span><strong>Jamie Morgan</strong></div><div><span>Visiting care partner</span><strong>Robin Chen</strong></div></div></div><div class="card"><h2 style="font-size:16px">A few things to remember</h2><p class="plan-caption">Evelyn enjoys gardening, mystery novels, and a quiet morning. Bring the appointment folder to clinic visits. Leave time between activities for a break.</p><p style="font-size:10px;color:var(--muted)">Synthetic profile · Demo reminders contain no drug or dosage details.</p></div></div><div class="card plan-schedule"><table class="plan-table"><thead><tr><th scope="col">Time</th><th scope="col">Plan</th><th scope="col">Where</th><th scope="col">Care partner</th><th scope="col">Status</th></tr></thead><tbody>${events.map(e=>{let label='';if(last!==e.date){last=e.date;label=`<tr class="date-separator"><td colspan="5">${fmt(fromKey(e.date),{weekday:'long',month:'long',day:'numeric'})}</td></tr>`}return `${label}<tr><td>${formatTime(e.time)}<br><small>${e.duration} min</small></td><td><strong>${escapeHtml(e.title)}</strong>${e.notes?`<br><small>${escapeHtml(e.notes)}</small>`:''}</td><td>${escapeHtml(e.location||'—')}</td><td>${escapeHtml(e.partner)}</td><td>${state.completed.includes(e.id)?'Complete':'Planned'}</td></tr>`}).join('')||'<tr><td colspan="5">No events planned for this week.</td></tr>'}</tbody></table></div><p class="plan-caption">Fictional demo by Danny Byrne · Changes are saved only in this browser. This document is a demonstration of scheduling software.</p></section>`}
function about(){return `<section>${heading('BEHIND THE DEMO','Thoughtful care. Practical engineering.','An independent portfolio project by Danny Byrne.',false)}<div class="card about-copy"><h2>What you can try</h2><p>Explore a care overview, check off daily tasks, add or edit appointments, navigate weeks, and print a shared care plan. Changes persist locally; “Reset demo” restores the fictional starting schedule.</p><h2>How it works</h2><p>This is a fresh implementation of care coordination workflows. It uses semantic HTML, CSS, and browser JavaScript, with no backend, sign-in, or service credentials. All people, events, and locations are synthetic.</p><p>Events use a single shared data model across the overview, calendar, and print view. The calendar places overlapping events in separate columns. Browser storage preserves edits, and a print stylesheet formats the weekly plan for landscape paper or PDF.</p><h2>Project scope</h2><p>This demo is independent of Microsoft and contains no Microsoft product source or branding. It illustrates care coordination concepts relevant to my frontend experience. It is not a clinical system and does not provide medication or treatment instructions.</p><h2>Explore the implementation</h2><p><code>app.js</code> contains state, fixtures, calendar layout, and interaction logic. <code>styles.css</code> includes responsive layouts and print styles. The project runs on any static web host.</p><a href="https://github.com/danny-byrne" target="_blank" rel="noopener noreferrer">Danny Byrne on GitHub ↗</a></div></section>`}
function render(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark" aria-hidden="true">✳</span>kindred</div><div class="brand-sub">A LITTLE MORE CARE</div><div class="nav-label">YOUR SHARED SPACE</div><nav class="nav" aria-label="Main navigation">${[['overview','home','Overview'],['calendar','calendar','Calendar'],['plan','heart','Care plan'],['about','info','About']].map(([view,svg,label])=>`<button data-view="${view}" class="${view===currentView?'active':''}" ${view===currentView?'aria-current="page"':''}>${icon(svg)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-note"><strong>${icon('leaf')} A space to explore</strong><p>Fictional people. Real interactions.<br>Make this little demo your own.</p><button class="text-button" data-action="reset">Reset demo ↻</button></div><div class="author"><div class="avatar">DB</div><div><p>Danny Byrne</p><small>PORTFOLIO PROJECT</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Your shared space <span>/</span> <strong>${displayNames[currentView]}</strong></div><div class="top-tools"><small class="top-date" style="font-size:11px;color:var(--muted)">${fmt(today,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</small><span class="pill"><span class="dot"></span> FICTIONAL DEMO</span><div class="avatar" aria-label="Alex Morgan, demo care coordinator">AM</div></div></header><main id="main" class="main" tabindex="-1">${({overview,calendar:calendarView,plan:carePlan,about}[currentView])()}<footer class="bottom-note"><span>Made with care · An independent demo by Danny Byrne</span><span>${storageAvailable?'Changes stay in your browser':'Changes last for this visit'} · <button class="text-button" data-action="reset">Reset demo</button></span></footer></main></div></div>`}
function editEvent(id){const e=state.events.find(e=>e.id===id);if(id&&!e)return;const form=document.getElementById('event-form');form.reset();const defaults=e||{id:'',title:'',date:currentView==='overview'?selected:dateKey(week),time:'10:00',duration:60,category:'appointment',location:'',partner:'Alex Morgan',notes:''};for(const [key,value] of Object.entries(defaults)){if(form.elements.namedItem(key))form.elements.namedItem(key).value=value}document.getElementById('event-title').textContent=e?'Appointment details':'Add an appointment';document.getElementById('delete-event').hidden=!e;document.getElementById('event-dialog').showModal();form.elements.title.focus()}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.view){go(button.dataset.view);return}if(button.hasAttribute('data-close')){button.closest('dialog').close();return}if(button.dataset.edit){editEvent(button.dataset.edit);return}if(button.dataset.day){selected=button.dataset.day;render();return}if(button.dataset.check){const id=button.dataset.check;state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];save();render();return}switch(button.dataset.action){case 'add':editEvent();break;case 'prev':week=addDays(week,-7);render();break;case 'next':week=addDays(week,7);render();break;case 'today':week=monday(today);render();break;case 'print':if(currentView!=='plan')go('plan');window.print();break;case 'reset':document.getElementById('reset-dialog').showModal();break}});
document.getElementById('event-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));values.title=values.title.trim();if(!values.title){form.elements.title.setCustomValidity('Please enter an appointment title.');form.elements.title.reportValidity();return}const start=minutes(values.time),duration=Number(values.duration);if(start<480||start+duration>1140){form.elements.time.setCustomValidity('Choose a time between 8 AM and 7 PM, including the appointment duration.');form.elements.time.reportValidity();return}const existing=Boolean(values.id);values.id=values.id||crypto.randomUUID();values.duration=duration;const index=state.events.findIndex(e=>e.id===values.id);if(index<0)state.events.push(values);else state.events[index]=values;week=monday(fromKey(values.date));selected=values.date;save();document.getElementById('event-dialog').close();render();notify(existing?'Appointment updated. Everyone’s on the same page.':'Appointment added to your shared plan.')});
for(const name of ['time','duration','title'])document.getElementById('event-form').elements[name].addEventListener('input',()=>{document.getElementById('event-form').elements.time.setCustomValidity('');document.getElementById('event-form').elements.title.setCustomValidity('')});
document.getElementById('delete-event').addEventListener('click',()=>{const id=document.getElementById('event-form').elements.id.value;state.events=state.events.filter(e=>e.id!==id);state.completed=state.completed.filter(x=>x!==id);save();document.getElementById('event-dialog').close();render();notify('Appointment removed from the plan.')});
document.getElementById('confirm-reset').addEventListener('click',()=>{state=seed();week=monday(today);selected=dateKey(today);save();document.getElementById('reset-dialog').close();render();notify('A fresh start. Demo schedule restored.')});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['overview','calendar','plan','about'].includes(next)){currentView=next;render()}});
render();
